package mapdb

import (
	"bytes"
	"fmt"
	"strings"

	"go.keploy.io/server/v3/pkg/models"
	"go.keploy.io/server/v3/pkg/platform/yaml"
	"go.keploy.io/server/v3/pkg/provenswitch"
	"go.keploy.io/server/v3/utils"
	"go.uber.org/zap"
	yamlLib "gopkg.in/yaml.v3"
)

// versionLine starts the comment line keploy writes at a mapping file's head
// (utils.GetVersionAsComment).
const versionLine = "# Generated by Keploy"

// header says when a writer starts a mapping file it writes with keploy's
// "# Generated by Keploy" line, as it always has: on every write
// (headerAlways), on a file it creates (headerOnNew), or never
// (headerNever). Under the proven switch a file's own head comes first.
type header int

const (
	headerNever header = iota
	headerOnNew
	headerAlways
)

// encodeOver encodes mapping in format to replace old, the file's bytes
// before (nil for a new file), as a writer of the file (testSetID's) writes
// it. Without the proven switch, and for JSON, it is the encoding, with
// keploy's line where the writer always put it (h): the file is written as
// keploy wrote it before it kept hand edits. Under the switch a YAML file
// keeps what a hand edit added to old (EncodeOver), and keploy says what it
// could not keep, so an edit is never lost without a word.
func (db *MappingDb) encodeOver(mapping *models.Mapping, format yaml.Format, old []byte, h header, testSetID string) ([]byte, error) {
	if format != yaml.FormatYAML || !provenswitch.On() {
		data, err := EncodeMappingF(mapping, db.logger, format)
		if err != nil || format != yaml.FormatYAML {
			return data, err
		}
		if h == headerAlways || h == headerOnNew && old == nil {
			data = append([]byte(utils.GetVersionAsComment()), data...)
		}
		return data, nil
	}
	data, unkept, err := encodeYAMLOver(mapping, old, nil, h)
	if err != nil {
		db.logger.Error("failed to marshal mapping", zap.Error(err))
		return nil, err
	}
	if unkept.Comments > 0 {
		db.logger.Warn(fmt.Sprintf("keploy rewrote the set's mappings file and dropped %d comment line(s) it could not place again", unkept.Comments),
			zap.String("testSetID", testSetID),
			zap.String("next_step", "keploy keeps the comment lines a mappings file starts with, comments on the keys it writes, and every field it does not know on the entries it writes; move a note to the top of the file"))
	}
	if len(unkept.Fields) > 0 {
		db.logger.Warn(fmt.Sprintf("keploy rewrote the set's mappings file and could not keep %d field(s) a hand edit added: each brings in more than %d YAML nodes through aliases", len(unkept.Fields), maxAliasNodes),
			zap.String("testSetID", testSetID), zap.Strings("fields", unkept.Fields),
			zap.String("next_step", "write the field's value out without aliases (*name), and keploy keeps it"))
	}
	if len(unkept.Dropped) > 0 {
		db.logger.Warn(fmt.Sprintf("keploy rewrote the set's mappings file and dropped %d field(s) a hand edit added to entries the new file does not have", len(unkept.Dropped)),
			zap.String("testSetID", testSetID), zap.Strings("fields", unkept.Dropped),
			zap.String("next_step", "the entry each field was on is gone from the file (removed, or its call recorded anew): add the field again where it belongs now"))
	}
	return data, nil
}

// Unkept is what a rewrite of a mapping file could not keep of the file it
// replaced (EncodeOver): how many of its comment lines; Fields, the fields a
// hand edit added that keploy could not write again (aliases bring in too
// much); and Dropped, the fields a hand edit added to items the new file
// does not have (a test it removed, a mock entry whose call it removed or
// recorded anew), which have nowhere to go. A mock entry the rewrite moved
// to another list keeps its fields there. Each field is named by where it
// was, as tests[o::TestB].mock_entries[mock-1].note.
type Unkept struct {
	Comments int
	Fields   []string
	Dropped  []string
}

// EncodeOver is mapping encoded as YAML to replace old, the mapping file's
// bytes before (nil for a new file), as keploy writes the file under the
// proven switch: with what a hand edit added to old (keepEdits), and the
// comment lines old starts with, its "# Generated by Keploy" line brought up
// to this keploy, or this keploy's line when old starts with none. A writer
// outside this package that builds the file anew (enterprise's per-test
// commit) writes it with this, and says what it could not keep.
//
// renames is how the rewrite named the mocks of old in the new file: nil
// when each mock keeps its name, so an old entry is the new entry of its
// name. Otherwise it names every mock the rewrite carried, one that keeps
// its name too (mock-2 to mock-2): an old entry naming mock n is the new
// entry naming renames[n], and an old entry whose mock renames lacks has no
// new entry: the rewrite did not carry that call, and a new entry that holds
// the name n now is another call, so a hand edit never moves to it
// (Unkept.Dropped). enterprise's per-test commit passes the map it renames
// the carried mocks with, {"mock-1": "mock-3"} for a call recorded as mock-1
// it carries past a new recording's mock-0 to mock-2.
func EncodeOver(mapping *models.Mapping, old []byte, renames map[string]string) ([]byte, Unkept, error) {
	return encodeYAMLOver(mapping, old, renames, headerAlways)
}

// encodeYAMLOver is EncodeOver with keploy's line where h puts it when old
// starts with no comment.
func encodeYAMLOver(mapping *models.Mapping, old []byte, renames map[string]string, h header) ([]byte, Unkept, error) {
	data, err := yaml.MarshalGeneric(yaml.FormatYAML, mapping)
	if err != nil {
		return nil, Unkept{}, err
	}
	var unkept Unkept
	data, unkept.Fields, unkept.Dropped = keepEdits(old, data, renames)
	head := commentHead(old)
	switch {
	case len(head) > 0:
		data = append(head, data...)
	case h == headerAlways || h == headerOnNew && old == nil:
		data = append([]byte(utils.GetVersionAsComment()), data...)
	}
	unkept.Comments = droppedComments(old, data)
	return data, unkept, nil
}

// commentHead is the comment lines data starts with, and the blank lines
// between them, its "# Generated by Keploy" line replaced by this keploy's;
// nil when data starts with no comment. A document marker (---) or a
// directive (%YAML) before them is skipped: the writer writes neither.
func commentHead(data []byte) []byte {
	var head bytes.Buffer
	blanks := 0
	for _, line := range strings.SplitAfter(string(data), "\n") {
		t := strings.TrimSpace(line)
		if t == "" {
			blanks++
			continue
		}
		if head.Len() == 0 && (t == "---" || strings.HasPrefix(t, "%")) {
			continue
		}
		if !strings.HasPrefix(t, "#") {
			break
		}
		if head.Len() > 0 {
			head.WriteString(strings.Repeat("\n", blanks))
		}
		blanks = 0
		if strings.HasPrefix(t, versionLine) {
			head.WriteString(utils.GetVersionAsComment())
			continue
		}
		head.WriteString(strings.TrimRight(line, "\r\n") + "\n")
	}
	if head.Len() == 0 {
		return nil
	}
	return head.Bytes()
}

// droppedComments is how many of the comment lines old, a mapping file's
// bytes before a rewrite, holds that written, its bytes after, does not:
// each line counted as often as it appears, a "# Generated by Keploy" line
// not at all (a rewrite brings it up to date). A comment the rewrite kept,
// at the head, on a key keploy writes, or beside a field keploy does not
// know, is not dropped. 0 for old that does not parse.
func droppedComments(old, written []byte) int {
	if !bytes.Contains(pastHead(old), []byte("#")) {
		// Every comment is in the head, which a rewrite keeps: no file is
		// parsed (a recording's batches rewrite the file often).
		return 0
	}
	kept := map[string]int{}
	for _, l := range commentTexts(written) {
		kept[l]++
	}
	n := 0
	for _, l := range commentTexts(old) {
		if kept[l] > 0 {
			kept[l]--
			continue
		}
		n++
	}
	return n
}

// pastHead is data after the comment and blank lines it starts with, and a
// document marker or directive before them (commentHead).
func pastHead(data []byte) []byte {
	comments := false
	for len(data) > 0 {
		line := data
		if i := bytes.IndexByte(data, '\n'); i >= 0 {
			line = data[:i+1]
		}
		t := bytes.TrimSpace(line)
		switch {
		case len(t) == 0:
		case t[0] == '#':
			comments = true
		case !comments && (string(t) == "---" || t[0] == '%'):
		default:
			return data
		}
		data = data[len(line):]
	}
	return nil
}

// commentTexts is the comment lines the YAML document data holds, wherever
// they are, each trimmed, without the "# Generated by Keploy" line; nil for
// data that does not parse.
func commentTexts(data []byte) []string {
	if len(data) == 0 {
		return nil
	}
	var doc yamlLib.Node
	if yamlLib.Unmarshal(data, &doc) != nil {
		return nil
	}
	var out []string
	var walk func(*yamlLib.Node)
	walk = func(x *yamlLib.Node) {
		for _, c := range []string{x.HeadComment, x.LineComment, x.FootComment} {
			for _, l := range strings.Split(c, "\n") {
				if l = strings.TrimSpace(l); strings.HasPrefix(l, "#") && !strings.HasPrefix(l, versionLine) {
					out = append(out, l)
				}
			}
		}
		for _, child := range x.Content {
			walk(child)
		}
	}
	walk(&doc)
	return out
}
